class Gisafirst {
    public static void main(String[] args) {
        int[] a = {4, 7, 1, 2};
        for(int i=0; i<3; i++) {
            for(int j=i+1; j<4; j++) {
                if(a[i] > a[j]) {
                    int temp = a[j];
                    a[j] = a[i];
                    a[i] = temp;
                }
            }
        }
        for(int i=0; i<4; i++) {
            System.out.print(a[i] + "a");
        }
    }
}

